local UIEventProxy = CS.Engine.UI.UIEventProxy
local KTool = CS.Engine.Lib.KTool

local BG_STATUS = {
    NORMAL = 1, -- 普通
    SELECT = 2, -- 选中
    FINISH = 3, -- 完成
}
local TEXT_STATUS = {
    NORMAL = 1, -- 普通
    SELECT = 2, -- 选中
    LOCKED = 3, -- 锁定
}

--- from: Assets/BundleResources/Prefabs/Activity/ActivityRegressionPanel900101.prefab > name: BtnDayNode
---@class RegressionTaskDayNode
---@field Env                           	RegressionTaskDayNode                   
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field CommonRedPoint                	UnityEngine.RectTransform
---@field ImgComplete                   	UnityEngine.RectTransform
---@field TextDay                       	UnityEngine.RectTransform
---@field Lock                          	UnityEngine.RectTransform
---@field UnLock                        	UnityEngine.RectTransform
---@field TxtProgress                   	TMPro.TextMeshProUGUI
---@field TextNumber                    	TMPro.TextMeshProUGUI
---@field ImgBg                         	Game.Native.Common.UISwitchImage
---@field BtnDayNode                    	UnityEngine.UI.Button
local RegressionTaskDayNode = Class("RegressionTaskDayNode")

function RegressionTaskDayNode:__init()
    self.btnAction   = nil
end

function RegressionTaskDayNode:__delete()
    self.btnAction   = nil
    self.controller  = nil
end

---SetCallBack
---设置单击回调函数
function RegressionTaskDayNode:SetBtnCallBack(cb)
    self.btnAction = cb
end

function RegressionTaskDayNode:GetCellDt()
    return checkTable(self.cellDt)
end

function RegressionTaskDayNode:GetToday()
    return tonumber(self.curDay)
end

function RegressionTaskDayNode:GetProgress()
    return tonumber(self:GetCellDt().progress)
end

function RegressionTaskDayNode:GetTotal()
    return tonumber(self:GetCellDt().count)
end

function RegressionTaskDayNode:GetDay()
    return tonumber(self:GetCellDt().day)
end


function RegressionTaskDayNode:Awake()
    SetButtonAction(self.controller.gameObject, function ()
        if type(self.btnAction) == 'function' then
            self.btnAction()
        end
    end)
end

function RegressionTaskDayNode:FreshBaseUI(data, curDay, isSelected)
    self.cellDt = checkTable(data)
    self.curDay = tonumber(curDay)

    self.TextNumber.text  = self:GetDay()
    self.TxtProgress.text = string.format("%s/%s", self:GetProgress(), self:GetTotal())
    local isLocked        = self:GetToday() < self:GetDay()
    KTool.SetActive(self.Lock.gameObject, isLocked)

    self:FreshSelectStatus(isSelected)
end

function RegressionTaskDayNode:FreshSelectStatus(status)
    local isLocked   = self:GetToday() < self:GetDay()
    local isComplete = self:GetProgress() == self:GetTotal()
    local isSelected = checkBool(status)

    CfUtils.SetUISwitchText(self.TextDay, isSelected and TEXT_STATUS.SELECT or TEXT_STATUS.NORMAL)
    CfUtils.SetUISwitchText(self.TxtProgress, isSelected and TEXT_STATUS.SELECT or TEXT_STATUS.NORMAL)
    CfUtils.SetUISwitchText(self.TextNumber, isSelected and TEXT_STATUS.SELECT or (isLocked and TEXT_STATUS.LOCKED or TEXT_STATUS.NORMAL))
    CfUtils.SetUISwitchImage(self.ImgBg, isSelected and BG_STATUS.SELECT or (isComplete and BG_STATUS.FINISH or BG_STATUS.NORMAL))

    KTool.SetActive(self.TxtProgress, isSelected or (not isComplete and not isLocked))
    KTool.SetActive(self.ImgComplete, not isSelected and isComplete)
end

function RegressionTaskDayNode:AddProgress(num)
    self:GetCellDt().progress = self:GetCellDt().progress + checkInt(num)
    self.TxtProgress.text = string.format("%s/%s", self:GetProgress(), self:GetTotal())
end

function RegressionTaskDayNode:DelRedCount(num)
    self:GetCellDt().redCount = self:GetCellDt().redCount - checkInt(num)
end

function RegressionTaskDayNode:UpdateRedPointStatus(status)
    KTool.SetActive(self.CommonRedPoint, self:GetCellDt().redCount >= 1)
end

function RegressionTaskDayNode:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return RegressionTaskDayNode